insert into public.publication_posts
  (publication, slug, n, hook, narration, beats, caption, published, date, ts, taxon, still, wide, gallery, clip_id, permalink, platform, updated_at) values
  ('usingitup', 'this-jar-is-on-refill-nine', 2, 'this jar is on refill nine', '["this jar is on refill nine.","the label wore off somewhere around the third one, and i just kept pouring into it.","the pantry doesn''t grow anymore — the same glass keeps coming back to the same spot.","nine refills is nine containers i never brought home."]'::jsonb, '[]'::jsonb, 'same glass, ninth time filled', true, '2026-09-13T00:05:12.706Z', 1789257912706, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250251.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250251.jpg', '[]'::jsonb, 'ucgen-1788398102984-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'nothing-on-this-shelf-is-new', 3, 'nothing on this shelf is new', '["nothing on this shelf is new.","every single thing here has been in use for years, and none of it has failed me yet.","i stopped replacing things the moment i realized none of them were actually broken.","the shelf looks calm because nothing new keeps arriving to crowd it."]'::jsonb, '[]'::jsonb, 'still working, still here', true, '2026-09-12T00:38:34.267Z', 1789173514267, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-29532438.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-29532438.jpg', '[]'::jsonb, 'ucgen-1788310833042-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-eat-every-meal-here', 4, 'a seam i sewed once', '["a seam i sewed once.","it held for a while."]'::jsonb, '[]'::jsonb, 'the marks on it are just proof i ate here', true, '2026-09-11T01:18:09.410Z', 1789089489410, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-7239153.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-7239153.jpg', '[]'::jsonb, 'ucgen-1788229530343-0', 'https://www.instagram.com/reel/Cx0000000fb/', 'instagram', '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-sponge-is-on-its-last-week', 5, 'this sponge is on its last week', '["this sponge is on its last week.","it started as a full block back in march, and it''s been thinning out ever since.","it still gets the plates clean — it just does it smaller now.","when it finally goes, there''s one more under the sink, and that''s the whole supply."]'::jsonb, '[]'::jsonb, 'washing up with the last of it', true, '2026-09-10T00:38:18.117Z', 1789000698117, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-6195931.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-6195931.jpg', '[]'::jsonb, 'ucgen-1788137405845-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-counter-has-stayed-empty', 6, 'this counter has stayed empty', '["this counter has stayed empty.","nothing new has landed on it in about a year — not because i''m strict, i just stopped needing the next thing.","what''s out is what i touch every day. the rest lives in a drawer and gets used from there.","an empty counter isn''t a style. it''s just nothing sitting around waiting for me."]'::jsonb, '[]'::jsonb, 'the counter stayed empty and i stopped noticing', true, '2026-09-09T00:19:14.766Z', 1788913154766, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-39109105.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-39109105.jpg', '[]'::jsonb, 'ucgen-1788052764686-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'these-towels-are-older-than-the-machine', 7, 'these towels are older than the machine', '["these towels are older than the machine that washes them","they''ve gone thin in the middle and they still dry me off fine","i fold them the same way i always have and they go back in the same drawer","nothing in this pile is waiting to be replaced"]'::jsonb, '[]'::jsonb, 'the pile that never needs restocking', true, '2026-09-08T00:22:00.084Z', 1788826920084, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-9153377.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-9153377.jpg', '[]'::jsonb, 'ucgen-1787965361335-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'these-plates-outlasted-three-moves', 8, 'these plates outlasted three moves', '["these plates outlasted three moves.","they were secondhand when i got them, and they didn''t match then either.","two of them are chipped on the rim, and i stopped counting that as a reason to replace anything.","i wash them, i dry them, i put them back. that''s it. that''s the whole thing."]'::jsonb, '[]'::jsonb, 'the chip is just where it''s been', true, '2026-09-07T00:24:29.879Z', 1788740669879, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-5904043.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-5904043.jpg', '[]'::jsonb, 'ucgen-1787878518900-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'ive-washed-these-plates-a-thousand-times', 9, 'i''ve washed these plates a thousand times', '["i''ve washed these plates a thousand times","there are four of them and one has a chip on the rim, and it still holds a full dinner just fine","i used to think a matching set would make the table feel more like mine, but it''s the washing that does that","so they go back in the rack, and tomorrow i''ll wash them again"]'::jsonb, '[]'::jsonb, 'same four plates, same sink, every night', true, '2026-09-06T00:25:26.103Z', 1788654326103, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-7641501.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-7641501.jpg', '[]'::jsonb, 'ucgen-1787797209358-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-refilled-this-jar-again', 10, 'i refilled this jar again', '["i refilled this jar again.","it''s the same jar it was last year, just fuller than it was on tuesday.","i didn''t buy a matching set or a new lid, i bought the bag and poured it in.","the pantry stopped being a project and started being a place i take things from."]'::jsonb, '[]'::jsonb, 'the jar was never the problem, the wanting a new one was', true, '2026-09-05T00:06:03.322Z', 1788566763322, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250247.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250247.jpg', '[]'::jsonb, 'ucgen-1787709359275-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-shelf-holds-what-i-use', 11, 'this shelf holds what i use', '["this shelf holds what i use","there are eight things on it and i touch every one of them in a week","the empty space used to feel like something i hadn''t finished buying yet","now it''s just room, and i''m the version of me who shops this shelf before anywhere else"]'::jsonb, '[]'::jsonb, 'one shelf, eight things, nothing waiting to be used', true, '2026-09-04T00:07:35.108Z', 1788480455108, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-5823684.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-5823684.jpg', '[]'::jsonb, 'ucgen-1787622076054-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'everything-here-has-a-second-life', 13, 'everything here has a second life', '["everything on this shelf has a second life.","the containers held something else before i refilled them, and the bowls came from a set that lost half its pieces.","i stopped throwing out the survivors and started building around them.","now the shelf is small, and it is finished."]'::jsonb, '[]'::jsonb, 'the shelf stopped growing and i stopped wanting', true, '2026-09-02T00:24:36.918Z', 1788308676918, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-6963727.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-6963727.jpg', '[]'::jsonb, 'ucgen-1787446117024-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-kettle-came-with-the-apartment', 14, 'this kettle came with the apartment', '["this kettle came with the apartment","it was here on the counter before i was, and i never questioned it","the handle sits a little loose in my hand but the water still boils in four minutes","i make tea in it every morning and it has never once occurred to me to replace it"]'::jsonb, '[]'::jsonb, 'the counter came stocked and i never questioned it', true, '2026-09-01T00:33:19.544Z', 1788222799544, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-39122055.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-39122055.jpg', '[]'::jsonb, 'ucgen-1787358930980-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-wrote-the-list-instead', 15, 'i wrote the list instead', '["i wrote the list instead","every time i wanted something i put it on this page instead of in a cart","a week later i read the page back and half of it had stopped sounding like me","what''s still written down after that is the part i actually needed"]'::jsonb, '[]'::jsonb, 'the page holds it so i don''t have to', true, '2026-08-31T00:17:02.267Z', 1788135422267, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-37116258.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-37116258.jpg', '[]'::jsonb, 'ucgen-1787273122158-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'these-shirts-keep-coming-back', 16, 'these shirts keep coming back', '["these shirts keep coming back","the same stack comes out of the wash every week and goes right back on the shelf","folding them is the whole maintenance plan, and it has been for a long time","i don''t have a list of what to replace, because nothing in this pile is asking"]'::jsonb, '[]'::jsonb, 'the same pile, week after week, and it still folds up fine', true, '2026-08-30T00:17:42.360Z', 1788049062360, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-6391698.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-6391698.jpg', '[]'::jsonb, 'ucgen-1787187654731-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-scraped-this-jar-clean', 17, 'i scraped this jar clean', '["I scraped this jar clean.","I kept reaching for it until there was nothing left.","No replacement, no new version—just the jar already here.","The empty space feels like a small exhale."]'::jsonb, '[]'::jsonb, 'the quiet satisfaction of finishing what i have', true, '2026-08-29T00:26:12.272Z', 1787963172272, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-6664527.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-6664527.jpg', '[]'::jsonb, 'ucgen-1787101405546-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-shop-this-shelf-first', 18, 'i shop this shelf first', '["I shop this shelf first.","I check what is already here before wanting anything else.","Seeing it all together makes the urge feel quieter.","Most wants pass long before this shelf runs out."]'::jsonb, '[]'::jsonb, 'Turns out, enough is easier to see when it has a place.', true, '2026-08-28T00:16:43.396Z', 1787876203396, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-7279829.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/tidy-minimal-shelf-7279829.jpg', '[]'::jsonb, 'ucgen-1787058086011-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-jar-has-been-refilled-since-january', 19, 'this jar has been refilled since january', '["this jar has been refilled since january","i bought it full one time and never bought the jar again","when it gets low i tip in more from the bag on the shelf","same glass, same lid, eight months of the same small routine"]'::jsonb, '[]'::jsonb, 'the jar was the one-time purchase, not the routine', true, '2026-08-27T00:26:36.180Z', 1787790396180, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7772676.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7772676.jpg', '[]'::jsonb, 'ucgen-1786927006764-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'these-pans-came-with-the-kitchen', 20, 'these pans came with the kitchen', '["these pans came with the kitchen","the handles are scratched up and the bottoms are dull and every one of them still heats even","for a while i kept a mental note that i''d upgrade them someday, and then the someday just quietly went away","they cook everything i know how to make, so there''s nothing to fix"]'::jsonb, '[]'::jsonb, 'still cooking on the pans that came with the place.', true, '2026-08-26T01:20:24.469Z', 1787707224469, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-37856635.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-37856635.jpg', '[]'::jsonb, 'ucgen-1786883569503-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-table-wobbles-on-one-leg', 21, 'this table wobbles on one leg', '["this table wobbles on one leg.","for a while i had a tab open for a new one, the kind with the good joints.","then i folded a square of paper under the short foot and the wobbling stopped.","it''s held every meal since, and the tab is closed."]'::jsonb, '[]'::jsonb, 'still level, still here', true, '2026-08-25T00:40:40.754Z', 1787618440754, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-6950278.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-6950278.jpg', '[]'::jsonb, 'ucgen-1786843094059-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-emptied-this-jar-myself', 22, 'i emptied this jar myself', '["i emptied this jar myself.","it took fourteen months, and i scraped the sides every single time.","that last ring near the bottom took me a week to finish.","now it''s just glass, and i''m not in a hurry to fill it."]'::jsonb, '[]'::jsonb, 'clear glass and nothing wasted', true, '2026-08-24T00:12:09.686Z', 1787530329686, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-36526035.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-36526035.jpg', '[]'::jsonb, 'ucgen-1786756188130-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-kitchen-came-with-three-pans', 23, 'this kitchen came with three pans', '["this kitchen came with three pans","they were here before i was and they still cook everything i make","i keep thinking i should fill the counters and then i don''t","the empty part of this counter is the part i like most"]'::jsonb, '[]'::jsonb, 'three pans and a bare counter, still enough', true, '2026-08-23T00:17:06.894Z', 1787444226894, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-10568255.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-10568255.jpg', '[]'::jsonb, 'ucgen-1786671463505-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'three-lines-i-wrote-instead', 24, 'three lines i wrote instead', '["three lines i wrote instead","when i want something now i write it down on this page instead of buying it","the pen is right here and the checkout button is two rooms away in my head","most of what''s on this paper never turned into anything and i don''t miss a single line"]'::jsonb, '[]'::jsonb, 'the paper does the wanting for me now', true, '2026-08-22T00:05:01.540Z', 1787357101540, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-7872723.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-7872723.jpg', '[]'::jsonb, 'ucgen-1786597260931-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-sewed-this-hem-myself', 25, 'i sewed this hem myself', '["i sewed this hem myself.","it took nine minutes and a thread color that doesn''t quite match.","nobody has ever noticed, and i''ve worn it all year.","nine minutes and a mismatched thread, and i kept something i already love."]'::jsonb, '[]'::jsonb, 'the thread doesn''t match and it has never mattered', true, '2026-08-21T00:14:46.260Z', 1787271286260, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-32866095.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-32866095.jpg', '[]'::jsonb, 'ucgen-1786504633180-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-table-is-older-than-me', 26, 'this table is older than me', '["this table is older than me","it came out of my grandmother''s kitchen and every scratch on it happened before i was born","i eat here, i work here, i put the groceries down here, and it holds","i''ve never once opened a tab looking for a better one"]'::jsonb, '[]'::jsonb, 'i''ve never once opened a tab looking for a better one', true, '2026-08-20T00:03:40.721Z', 1787184220721, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-5806656.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-5806656.jpg', '[]'::jsonb, 'ucgen-1786417657097-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-kitchen-hasnt-needed-anything', 27, 'this kitchen hasn''t needed anything', '["this kitchen hasn''t needed anything","every surface you can see here has been the same since i moved in, and none of it has failed me","the drawer still slides, the burner still lights, the water still runs hot when i ask it to","somewhere along the way i stopped shopping for a kitchen and started just cooking in one"]'::jsonb, '[]'::jsonb, 'the counters look like this because i stopped adding to them', true, '2026-08-19T00:09:03.299Z', 1787098143299, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-34771926.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-34771926.jpg', '[]'::jsonb, 'ucgen-1786254067882-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'ive-filled-this-jar-from-the-same-bag-four-times-now', 28, 'i''ve filled this jar from the same bag four times now', '[]'::jsonb, '[]'::jsonb, 'the bag outlasts the wanting every time', true, '2026-08-18T12:04:41.493Z', 1787054681493, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250657.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250657.jpg', '[]'::jsonb, 'ucgen-1786156257675-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
