  ('usingitup', 'three-things-on-this-page-and-i-crossed-out-two-of-them', 31, 'three things on this page and i crossed out two of them without buying', '[]'::jsonb, '[]'::jsonb, 'turns out most wants have a shelf life of about a week', true, '2026-08-15T00:16:19.721Z', 1786752979721, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-31485697.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-31485697.jpg', '[]'::jsonb, 'ucgen-1785385458222-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
