  ('usingitup', 'every-pan-in-this-kitchen-is-older-than-the-apartment', 33, 'every pan in this kitchen is older than the apartment and they all still cook', '[]'::jsonb, '[]'::jsonb, 'nothing in here needs replacing yet', true, '2026-08-13T00:22:41.516Z', 1786580561516, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-36516361.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-36516361.jpg', '[]'::jsonb, 'ucgen-1785367277261-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'this-table-came-with-the-apartment-and-it-has-held', 34, 'this table came with the apartment and it has held every meal since', '[]'::jsonb, '[]'::jsonb, 'nothing here needed replacing', true, '2026-08-12T00:13:06.162Z', 1786493586162, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-6376690.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/simple-wooden-table-6376690.jpg', '[]'::jsonb, 'ucgen-1785361856229-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'nothing-on-these-counters-is-new-and-dinner-still-gets', 35, 'nothing on these counters is new and dinner still gets made every night', '[]'::jsonb, '[]'::jsonb, 'the kitchen doesn''t need an upgrade, it needs me to cook in it', true, '2026-08-11T00:04:51.533Z', 1786406691533, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-4068402.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-4068402.jpg', '[]'::jsonb, 'ucgen-1785350851993-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-learned-this-stitch-from-a-video-and-now-the-hole-is', 36, 'i learned this stitch from a video and now the hole is just gone', '[]'::jsonb, '[]'::jsonb, 'twelve minutes and it''s a shirt again 🧵', true, '2026-08-10T01:15:31.725Z', 1786324531725, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-8527778.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-8527778.jpg', '[]'::jsonb, 'ucgen-1785345429914-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-bought-this-jar-full-and-im-the-one-who-emptied-it', 37, 'i bought this jar full and i''m the one who emptied it', '[]'::jsonb, '[]'::jsonb, 'no ceremony, just the end of it', true, '2026-08-09T01:06:05.568Z', 1786237565568, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-7246458.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/empty-glass-jar-7246458.jpg', '[]'::jsonb, 'ucgen-1785340006450-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-sponge-is-on-its-last-week-and-the-plates-still', 38, 'the sponge is on its last week and the plates still come out clean', '[]'::jsonb, '[]'::jsonb, 'nothing here needs replacing yet', true, '2026-08-08T00:58:58.221Z', 1786150738221, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-9474970.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/washing-dishes-calm-9474970.jpg', '[]'::jsonb, 'ucgen-1785318268413-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-towels-are-thin-in-the-middle-and-dry-me-just-fine', 39, 'my towels are thin in the middle and dry me just fine', '["My towels are thin in the middle and they dry me just fine.","Thin isn''t the same as worn out. I had those two confused for a long time.","They still do the only job a towel has. Nothing about that has gotten worse.","The good ones don''t announce themselves. They just keep showing up."]'::jsonb, '[]'::jsonb, 'the good ones don''t announce themselves, they just keep showing up', true, '2026-07-23T21:23:11.844Z', 1784841791844, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-36633851.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-36633851.jpg', '[]'::jsonb, 'ucgen-1784571252655-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-desk-lamp-has-a-wobble-ive-stopped-noticing', 40, 'my desk lamp has a wobble i''ve stopped noticing', '["My desk lamp has a wobble that I stopped noticing years ago.","It''s been lighting this desk since my first apartment, through three moves it should not have survived.","Homework. Taxes. Every late draft I''ve ever been too tired to finish.","Eight years of my actual life, all of it under one crooked lamp."]'::jsonb, '[]'::jsonb, 'eight years of homework, taxes, and late drafts under one crooked lamp', true, '2026-07-22T02:58:52.817Z', 1784689132817, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-8051656.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/folding-laundry-8051656.jpg', '[]'::jsonb, 'ucgen-1784558861556-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-scissors-were-my-moms-and-they-still-cut-clean', 41, 'my scissors were my mom''s and they still cut clean through everything', '["My scissors were my mom''s, and they still cut clean through everything.","They''re older than I am by about a decade. Nobody thought of them as an heirloom.","The handles are worn smooth from two people''s hands. That''s not damage, that''s just use.","Nothing about them is new and nothing about them needs to be."]'::jsonb, '[]'::jsonb, 'nothing about them is new and nothing about them needs to be', true, '2026-07-22T00:22:09.578Z', 1784679729578, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-7560165.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/handwritten-list-paper-7560165.jpg', '[]'::jsonb, 'ucgen-1784552665365-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-blender-is-loud-and-ugly-and-has-never-once-failed', 42, 'my blender is loud and ugly and has never once failed to make the smoothie', '["My blender is loud and ugly and has never once failed to make the smoothie.","It sounds like a small engine starting up. The whole kitchen knows when I use it.","It matches absolutely nothing else in the room. It never has.","And nobody has ever asked me what brand it is. Not once, in all these years."]'::jsonb, '[]'::jsonb, 'nobody''s ever asked me what brand it is', true, '2026-07-21T17:53:31.591Z', 1784656411591, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-7303604.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/clean-minimal-kitchen-7303604.jpg', '[]'::jsonb, 'ucgen-1784514493648-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-winter-coat-is-on-its-eighth-year-and-the-pockets', 43, 'my winter coat is on its eighth year and the pockets know my hands', '["My winter coat is on its eighth year, and at this point the pockets know my hands.","One seam is repaired, badly, by me, on a night I decided that was easier than shopping.","And it has been warm every single winter since. Not one cold walk it failed at.","Nothing about it ever needed replacing. It just needed wearing."]'::jsonb, '[]'::jsonb, 'nothing about it needed replacing. it just needed wearing', true, '2026-07-21T16:11:11.230Z', 1784650271230, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-37673526.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/mending-sewing-hands-37673526.jpg', '[]'::jsonb, 'ucgen-1784508275012-0', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-last-scrape-of-the-jar-is-the-sound-of-not-needing', 44, 'the last scrape of the jar is the sound of not needing more yet', '["The last scrape of the jar is the sound of not needing more yet.","It isn''t empty. It''s finished. Those are two completely different states.","Empty is a gap. Finished is a small ending, and endings are allowed to feel good.","And there''s nothing to replace until tomorrow. Tonight it just gets to be done."]'::jsonb, '[]'::jsonb, 'yet.', true, '2026-07-21T14:25:23.356Z', 1784643923356, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', '[]'::jsonb, 'uc-30', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'wanting-less-isnt-deprivation-its-the-end-of-being', 45, 'wanting less isn''t deprivation. it''s the end of being advertised to in your own head', '["Wanting less isn''t deprivation. It''s the end of being advertised to inside your own head.","The ad used to keep playing long after I closed the app. That was the part nobody mentions.","It ran as a quiet list of everything I didn''t have yet. Always updating. Never finished.","Quiet is what''s left when that stops. It isn''t emptiness. It''s just the noise being gone."]'::jsonb, '[]'::jsonb, 'unsubscribed internally.', true, '2026-07-21T12:15:17.261Z', 1784636117261, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', '[]'::jsonb, 'uc-29', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-kitchen-has-fewer-things-and-more-room-to-cook-that', 46, 'my kitchen has fewer things and more room to cook. that was the trade', '["My kitchen has fewer things in it and more room to cook. That was the trade.","One good pan instead of five that were each perfect for one specific thing I never made.","Counter space I can actually put a cutting board on without moving three appliances first.","And I cook more now, not less. Fewer tools somehow made it easier to start."]'::jsonb, '[]'::jsonb, 'counter space is a lifestyle.', true, '2026-07-21T03:01:36.577Z', 1784602896577, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', '[]'::jsonb, 'uc-28', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-free-version-of-that-feeling-is-finishing-what-you', 47, 'the free version of that feeling is finishing what you have', '["The free version of that feeling is finishing what you already have.","What you''re after is the fresh start. The clean slate. The beginning of something.","An empty jar gives you the exact same thing. A real ending, and then a real beginning.","And it''s already paid for. I bought that feeling months ago and never collected it."]'::jsonb, '[]'::jsonb, 'already paid for.', true, '2026-07-21T00:20:09.508Z', 1784593209508, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', '[]'::jsonb, 'uc-27', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'one-in-one-out-was-too-gentle-now-its-one-out-then-well', 48, 'one in, one out was too gentle. now it''s one out, then we''ll see', '["One in, one out was too gentle for me. Now it''s one out, and then we''ll see.","One in, one out kept the count perfectly flat. Same amount of stuff, forever.","And flat wasn''t actually what I wanted. I wanted room, and flat never gives you room.","So I let the shelf get roomy first. Nothing has needed to come back yet."]'::jsonb, '[]'::jsonb, 'the shelf decides.', true, '2026-07-20T19:33:06.574Z', 1784575986574, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-26', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-replaced-the-scroll-and-buy-loop-with-finish-and', 49, 'i replaced the scroll-and-buy loop with finish-and-notice', '["I replaced the scroll and buy loop with a finish and notice one.","The old loop went: want something, order it, forget it existed by the time it showed up.","The new one goes: use what''s here, finish it, and actually notice that you did.","Same brain. Same reward it was looking for. Just wired into something I get to keep."]'::jsonb, '[]'::jsonb, 'different loop, different life.', true, '2026-07-20T17:23:08.040Z', 1784568188040, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', '[]'::jsonb, 'uc-25', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'it-still-works-thats-the-whole-review', 50, 'it still works. that''s the whole review', '["It still works. That''s the whole review.","There are no features I''m missing. I''ve checked, mostly out of curiosity.","There''s no problem here waiting to be solved by something newer. Nothing is going wrong.","Working is the highest rating there is. Everything else is just marketing on top of it."]'::jsonb, '[]'::jsonb, 'five stars, six years.', true, '2026-07-20T14:20:53.945Z', 1784557253945, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', '[]'::jsonb, 'uc-24', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'stuff-stopped-arriving-and-peace-started', 51, 'stuff stopped arriving and peace started', '["Stuff stopped arriving, and peace started. Almost immediately.","There are no boxes by the door. No cardboard pile I keep meaning to break down.","Nothing waiting to be unpacked, assessed, kept or returned before some deadline.","The doorstep got boring. It turns out boring was what I was looking for."]'::jsonb, '[]'::jsonb, 'quiet doorstep, quiet head.', true, '2026-07-20T12:12:38.377Z', 1784549558377, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-23', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-version-of-me-that-burns-the-fancy-candle-instead', 52, 'the version of me that burns the fancy candle instead of saving it', '["I''m becoming the version of me who burns the fancy candle instead of saving it.","It sat unlit for two years, waiting for an occasion that apparently never qualified.","Saving it wasn''t respect. It was just a slow way of never getting to have it.","It''s a Tuesday. I lit it anyway. The occasion was me."]'::jsonb, '[]'::jsonb, 'lit it on a tuesday.', true, '2026-07-20T02:02:58.799Z', 1784512978799, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', '[]'::jsonb, 'uc-22', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-romanticize-the-almost-empty-bottle-now-it-means-i', 53, 'i romanticize the almost-empty bottle now. it means i showed up every day', '["I romanticize the almost empty bottle now. It means I showed up every day.","You can actually see the routine through the glass. The level going down is the proof.","That''s months of completely ordinary mornings stacked up into one small measurable thing.","That''s what almost empty means to me now. Not that it''s running out. That I was consistent."]'::jsonb, '[]'::jsonb, 'consistency you can see through.', true, '2026-07-20T00:18:23.143Z', 1784506703143, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', '[]'::jsonb, 'uc-21', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'new-isnt-a-feeling-it-just-borrows-one-for-a-week', 54, 'new isn''t a feeling. it just borrows one for a week', '["New isn''t a feeling. It just borrows one for about a week.","Day one, it''s genuinely exciting. You keep looking at it. That part is real.","Day nine, it''s an object in your house. You walk past it without seeing it.","The feeling was always rented. It was never actually included in the price."]'::jsonb, '[]'::jsonb, 'the feeling was never in the box.', true, '2026-07-19T19:59:39.741Z', 1784491179741, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', '[]'::jsonb, 'uc-20', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'pov-laundry-folded-nothing-ordered-nothing-on-the-way', 55, 'POV: laundry folded, nothing ordered, nothing on the way. stillness', '["Laundry folded. Nothing ordered. Nothing on the way. Just stillness.","There are no packages in transit right now. Not one.","Nothing to track, nothing to check on, nothing arriving that I have to open and find a place for.","The day just gets to be the day. I didn''t know how loud the waiting was until it stopped."]'::jsonb, '[]'::jsonb, 'no tracking numbers.', true, '2026-07-19T17:18:09.095Z', 1784481489095, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-laundry.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-laundry.jpg', '[]'::jsonb, 'uc-19', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'half-my-calm-came-from-finishing-things-i-already', 56, 'half my calm came from finishing things i already started', '["About half my calm came from finishing things I''d already started.","The bottle that sat almost empty for two months because I kept reaching past it.","The book with the bent corner, waiting on the nightstand under three newer ones.","Closing loops instead of opening new ones. That''s it. That was the whole change."]'::jsonb, '[]'::jsonb, 'closure in jar form.', true, '2026-07-19T14:42:48.042Z', 1784472168042, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-dishes.jpg', '[]'::jsonb, 'uc-18', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-cart-can-sit-there-wanting-fades-faster-than-regret', 57, 'the cart can sit there. wanting fades faster than regret', '["The cart can just sit there. Wanting fades a lot faster than regret does.","Give it seven days. That''s the whole method. There isn''t more to it.","Most of it goes quiet on its own. You open the tab later and feel almost nothing.","And whatever''s still loud after a week, I actually wanted. That''s the one I buy, and there''s no guilt left on it."]'::jsonb, '[]'::jsonb, 'seven days, and it went quiet.', true, '2026-07-19T12:07:28.533Z', 1784462848533, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', '[]'::jsonb, 'uc-17', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-know-exactly-what-i-own-now-that-used-to-not-be-true', 58, 'i know exactly what i own now. that used to not be true', '["I know exactly what I own now. That used to not be true at all.","I used to rebuy things I already had, sitting somewhere I''d never checked.","Twice. Sometimes three times. Two of the same thing in two different drawers.","Knowing is its own kind of quiet. Nothing hiding, nothing to guess at."]'::jsonb, '[]'::jsonb, 'inventory of a quiet life.', true, '2026-07-19T02:26:33.965Z', 1784427993965, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-16', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'buying-less-didnt-make-my-life-smaller-it-made-it', 59, 'buying less didn''t make my life smaller. it made it specific', '["Buying less didn''t make my life smaller. It made it specific.","There are fewer things now, and all of them are actually mine. Chosen, not accumulated.","Nothing in this room got here by accident, or by a sale, or by a bad night.","Smaller was never the point. Specific was the point. It just looks like less from outside."]'::jsonb, '[]'::jsonb, 'curated by use.', true, '2026-07-19T00:18:40.071Z', 1784420320071, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', '[]'::jsonb, 'uc-15', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-version-of-me-that-mends-the-hem-instead-of-opening', 60, 'the version of me that mends the hem instead of opening a tab', '["I''m becoming the version of me that mends the hem instead of opening a tab.","It took ten minutes and the stitches are genuinely not good. Nobody has ever noticed.","No package. No waiting three days. No tracking number living in my head.","I wore it out the same night. That''s the part the tab could never have done."]'::jsonb, '[]'::jsonb, 'ten minutes, zero packages.', true, '2026-07-18T19:35:24.445Z', 1784403324445, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-sewing.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-sewing.jpg', '[]'::jsonb, 'uc-14', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'you-dont-need-the-upgraded-version-you-need-to-remember', 61, 'you don''t need the upgraded version. you need to remember why you bought the first one', '["You probably don''t need the upgraded version. You need to remember why you bought the first one.","You chose it carefully once. You read about it. You waited for it.","And nothing about it has actually gotten worse since then. It does exactly what it did.","The ads just got better. That''s the only thing that changed."]'::jsonb, '[]'::jsonb, 'it was enough when you chose it.', true, '2026-07-18T17:02:16.549Z', 1784394136549, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', '[]'::jsonb, 'uc-13', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'every-empty-jar-is-a-receipt-for-patience', 62, 'every empty jar is a receipt for patience', '["Every empty jar is a receipt for patience.","You can''t rush one. There''s no way to skip to the end of a jar.","It only happens by showing up, a little at a time, for as long as it takes.","So an empty one is proof I stayed with something. I didn''t expect that to feel like anything."]'::jsonb, '[]'::jsonb, 'proof of use.', true, '2026-07-18T14:51:58.998Z', 1784386318998, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', '[]'::jsonb, 'uc-12', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-deleted-the-shopping-app-and-my-evenings-got-longer', 63, 'i deleted the shopping app and my evenings got longer', '["I deleted the shopping app, and my evenings got noticeably longer.","It was about twenty minutes a night. Browsing. Comparing. Not really buying.","And I never once noticed spending it. It didn''t feel like time, it felt like nothing.","Now the evening just sits there, open, waiting for me to do something real with it."]'::jsonb, '[]'::jsonb, 'time refund.', true, '2026-07-18T12:15:54.551Z', 1784376954551, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', '[]'::jsonb, 'uc-11', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-prettiest-shelf-in-my-house-is-the-one-with-space', 64, 'the prettiest shelf in my house is the one with space on it', '["The prettiest shelf in my house is the one with space left on it.","There are four things on it. All four get used in a normal week.","And there''s enough room to actually see each one instead of scanning past a wall of stuff.","The gap is the design. I didn''t buy it. I just stopped filling it."]'::jsonb, '[]'::jsonb, 'negative space is a purchase too.', true, '2026-07-18T02:14:54.950Z', 1784340894950, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-10', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'pov-you-wear-the-sneakers-until-theyre-actually-done', 65, 'POV: you wear the sneakers until they''re actually done and they tell the whole story', '["You wear the sneakers until they''re actually done, and by then they tell the whole story.","There''s the crease across the toe from every walk home, folded in a thousand times.","There''s the scuff on the side from that one trip you''d forgotten about until you looked down.","A new pair would know none of it. They''d be beautiful and completely blank."]'::jsonb, '[]'::jsonb, 'every scuff earned.', true, '2026-07-18T00:16:28.215Z', 1784333788215, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-laundry.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-laundry.jpg', '[]'::jsonb, 'uc-09', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'repair-is-a-love-language-you-can-have-with-your-own', 66, 'repair is a love language you can have with your own stuff', '["Repair is a love language, and you can have it with your own stuff.","A hem takes about ten minutes. Less if you stop trying to make it perfect.","A button takes four. I timed it once, mostly to prove to myself it was nothing.","And on the other side, you keep the thing you already liked. That''s the whole trade."]'::jsonb, '[]'::jsonb, 'mended > new.', true, '2026-07-17T21:39:49.550Z', 1784324389550, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-sewing.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-sewing.jpg', '[]'::jsonb, 'uc-08', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-wishlist-got-old-and-i-realized-i-didnt-want-most', 67, 'the wishlist got old and i realized i didn''t want most of it. i just wanted a different day', '["My wishlist got old, and I realized I didn''t want most of it. I just wanted a different day.","Half of it I couldn''t even remember adding. Somebody added it. It wasn''t quite me.","The wanting had a timestamp on it. It belonged to a specific bad afternoon, and that afternoon was over.","What I actually wanted was rest. It just showed up disguised as a cart."]'::jsonb, '[]'::jsonb, 'wanting fades. notice what stays.', true, '2026-07-17T19:31:04.519Z', 1784316664519, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-notebook.jpg', '[]'::jsonb, 'uc-07', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'using-it-up-is-more-satisfying-than-unboxing-it-nobody', 68, 'using it up is more satisfying than unboxing it. nobody tells you that', '["Using something up is more satisfying than unboxing it. Nobody tells you that part.","Unboxing is over in about ten seconds. Then it''s just a thing on a shelf.","Using it up takes months. Sometimes a year. You''re in it the whole time.","And only one of those did I actually earn. That''s the difference I can feel."]'::jsonb, '[]'::jsonb, 'the last scoop hits different.', true, '2026-07-17T17:49:34.395Z', 1784310574395, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', '[]'::jsonb, 'uc-06', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-stopped-replacing-things-that-still-work-and-suddenly', 69, 'i stopped replacing things that still work and suddenly i could breathe', '["I stopped replacing things that still worked, and suddenly I could breathe.","For the first time, nothing in my house was pending. Nothing was halfway to being swapped out.","No upgrade sitting open in a tab, quietly telling me what I have isn''t finished yet.","Turns out that was the noise. Not the stuff. The waiting to replace the stuff."]'::jsonb, '[]'::jsonb, 'the upgrade was stopping.', true, '2026-07-17T14:46:09.283Z', 1784299569283, 'feel-seen', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-kitchen.jpg', '[]'::jsonb, 'uc-05', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'an-abandoned-cart-is-a-small-quiet-win-nobody-claps-for', 70, 'an abandoned cart is a small quiet win nobody claps for. clap anyway', '["An abandoned cart is a small, quiet win that nobody claps for. So clap anyway.","Nobody posts the thing they didn''t buy. There''s no content in a closed tab.","There''s no unboxing video for restraint. No haul for the money still in your account.","So I count it myself. Quietly. That''s allowed."]'::jsonb, '[]'::jsonb, 'closed the tab. kept the peace.', true, '2026-07-17T12:11:17.934Z', 1784290277934, 'didnt-buy-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-list.jpg', '[]'::jsonb, 'uc-04', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-version-of-me-that-shops-her-own-shelves-first', 71, 'the version of me that shops her own shelves first', '["I''m becoming the version of me that shops her own shelves first.","Before anything else, she checks the back of the cabinet. The drawer she never opens.","And almost every time, it''s already in there. Bought months ago by a version of me who forgot.","So the list gets shorter on its own. Not from discipline. Just from looking."]'::jsonb, '[]'::jsonb, 'everything i need is already here.', true, '2026-07-17T02:03:08.547Z', 1784253788547, 'identity-arrival', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-03', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'my-headphones-are-six-years-old-and-thats-the-flex', 72, 'my headphones are six years old and that''s the flex', '["My headphones are six years old, and honestly, that''s the flex.","The cushions are worn into the exact shape of my ears at this point.","Three phones have come and gone since I bought them. They outlasted all of it.","And I still can''t find a single real reason to replace them. So I won''t."]'::jsonb, '[]'::jsonb, 'it still works. that''s the review.', true, '2026-07-16T23:20:30.013Z', 1784244030013, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-shelf.jpg', '[]'::jsonb, 'uc-02', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'i-finished-the-whole-bottle-before-buying-another-and', 73, 'i finished the whole bottle before buying another and it felt like a personality upgrade', '["I finished the whole bottle before buying another one, and honestly it felt like a personality upgrade.","There was no backup under the sink. No spare waiting for its turn.","Just one bottle, used all the way down to the last honest squeeze.","And the empty bottle turned out to be the reward. Not the new one. The finished one."]'::jsonb, '[]'::jsonb, 'use it up first.', true, null, 0, 'finished-it', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/uc-jar.jpg', '[]'::jsonb, 'uc-01', null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('usingitup', 'the-jar-i-did-not-replace', 2, 'the jar i did not replace', '["this jar is on refill nine.","the label wore off somewhere around the third one, and i just kept pouring into it.","the pantry doesn''t grow anymore — the same glass keeps coming back to the same spot.","nine refills is nine containers i never brought home."]'::jsonb, '[]'::jsonb, 'same glass, ninth time filled', true, '2026-09-13T00:05:12.706Z', 1789257912706, 'still-works', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250251.jpg', 'http://127.0.0.1:54321/storage/v1/object/public/publication/usingitup/objects/refilling-jar-pantry-7250251.jpg', '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('theweeklymend', 'the-light-at-six-forty', 41, 'the light at six forty', '[]'::jsonb, '[]'::jsonb, 'the light at six forty', true, '2026-09-15T08:48:00+00:00', 1789462080000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('theweeklymend', 'coffee-before-anyone-asks', 40, 'coffee before anyone asks', '[]'::jsonb, '[]'::jsonb, 'coffee before anyone asks', true, '2026-09-08T08:48:00+00:00', 1788857280000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('theweeklymend', 'the-kettle-is-the-alarm', 39, 'the kettle is the alarm', '[]'::jsonb, '[]'::jsonb, 'the kettle is the alarm', true, '2026-09-01T08:48:00+00:00', 1788252480000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('plainpantry', 'the-raise-i-did-not-ask-for', 22, 'the raise i did not ask for', '[]'::jsonb, '[]'::jsonb, 'the raise i did not ask for', true, '2026-09-14T20:07:00+00:00', 1789416420000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz),
  ('plainpantry', 'a-budget-that-fits-on-a-receipt', 21, 'a budget that fits on a receipt', '[]'::jsonb, '[]'::jsonb, 'a budget that fits on a receipt', true, '2026-09-07T20:07:00+00:00', 1788811620000, null, null, null, '[]'::jsonb, null, null, null, '2026-09-18T21:30:00+00:00'::timestamptz);
